Tool response:
Tool: find_lots_by_category_and_bid
Description: Find lots in a specific category with current bid under a specified amount.
Parameters:
    {
      "type": "object",
      "properties": {
        "category_name": {
          "type": "string",
          "description": "Name of the category to filter by (e.g., 'Fine Art')",
          "title": "Category Name"
        },
        "max_bid": {
          "type": "number",
          "description": "Maximum current bid amount to filter by (e.g., 2000.0)",
          "title": "Max Bid"
        }
      },
      "required": [
        "category_name",
        "max_bid"
      ]
    }

Tool response:
Tool: get_lot_details
Description: Retrieve detailed information about a specific lot.
Parameters:
    {
      "type": "object",
      "properties": {
        "lot_id": {
          "type": "integer",
          "title": "Lot Id",
          "description": ""
        }
      },
      "required": [
        "lot_id"
      ]
    }
